extends CharacterBody2D

@onready var nav_agent: NavigationAgent2D = $NavigationAgent2D
var speed = 200.0
var reached = false

func _ready():
	nav_agent.target_reached.connect(_on_target_reached)

func _physics_process(delta):
	if nav_agent.is_navigation_finished():
		return

	var next_path_pos = nav_agent.get_next_path_position()
	var direction = global_position.direction_to(next_path_pos)
	velocity = direction * speed
	move_and_slide()

func set_target(target: Vector2):
	reached = false
	nav_agent.target_position = target

func _on_target_reached():
	reached = true
	print("Agent reached target")

extends Node2D

@onready var nav_region: NavigationRegion2D = $NavigationRegion2D
@onready var agent: CharacterBody2D = $NavAgent
@onready var obstacle: StaticBody2D = $Obstacle

func bake_nav():
	var source_geometry_data = NavigationMeshSourceGeometryData2D.new()
	var traversable_outline = PackedVector2Array([Vector2(0, 0), Vector2(800, 0), Vector2(800, 600), Vector2(0, 600)])
	source_geometry_data.add_traversable_outline(traversable_outline)

	# Add obstacle as obstruction
	var obs_shape = obstacle.get_node("CollisionShape2D").shape
	if obs_shape is RectangleShape2D:
		var size = obs_shape.size
		var pos = obstacle.global_position
		var rect = Rect2(pos - size / 2, size)
		var outline = PackedVector2Array([rect.position, Vector2(rect.end.x, rect.position.y), rect.end, Vector2(rect.position.x, rect.end.y)])
		source_geometry_data.add_obstruction_outline(outline)

	var nav_poly = NavigationPolygon.new()
	NavigationServer2D.bake_from_source_geometry_data(nav_poly, source_geometry_data)
	nav_region.navigation_polygon = nav_poly
	print("Nav baked")

func move_obstacle(new_pos: Vector2):
	obstacle.global_position = new_pos
	bake_nav()

extends SceneTree

func _init():
	print("Running tests...")
	var root = get_root()
	var world = load("res://scenes/nav_world.tscn").instantiate()
	root.add_child(world)

	# Initial bake
	world.bake_nav()

	# Set goal
	var agent = world.get_node("NavAgent")
	agent.set_target(Vector2(750, 550))

	# Wait for a bit (simulate frames)
	await world.get_tree().create_timer(1.0).timeout

	if agent.reached:
		print("Test passed: Reached target.")
	else:
		print("Test failed: Did not reach target.")

	quit()
